/**
 * Cascade for a removed member: clears the assignee on every live issue they
 * held, publishing one `issue.unassigned` per issue. No `issue:assign` check
 * per issue — the caller has already authorized the removal, and the people
 * losing work are not the ones acting. Archived issues keep their assignee.
 */
export async function unassignIssuesAssignedTo(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<number> {
  assertOrgScope(actor, orgId);

  const held = await issueRepo.listLiveIssuesAssignedTo(orgId, userId);

  for (const issue of held) {
    const after = await issueRepo.setIssueAssignee(orgId, issue.id, null);
    await emit("issue.unassigned", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      previousAssigneeId: userId,
    });
  }

  return held.length;
}

